-- =============================================================================
-- LOCAL DB BASELINE — WeCMS-Vietnam tenant (VN_VNM0004_*)
-- Baseline tenant:  VN_VNM0004_000001  (CÔNG TY TNHH WEBCASH VIỆT NAM)
-- Valid tenants:    biz_key LIKE 'VN_VNM0004_%'  (all other tenants are invalid)
-- Target DB:        localhost:5434 / wecms_dev / schema public
-- Source:           JEX DEV DB (wecmsvndev), snapshot pulled 2026-04-23
-- Target tables:    busi_infm, user_infm, user_busi_conn_infm, user_login_his
--
-- WHAT THIS SCRIPT DOES
--   1. Pre-flight   — verifies FK lookup rows (natn_infm.VN, chnl_infm.VNM0004)
--   2. Cleanup      — deletes every row whose tenant is NOT VN_VNM0004_% across
--                     the 4 target tables (user_login_his purged by user_id
--                     join — it has no biz_key column)
--   3. Seed         — idempotently inserts the VN_VNM0004_000001 busi row, the
--                     99 users currently linked to it in DEV, and the 99
--                     user↔business connection rows.  All inserts use
--                     ON CONFLICT DO NOTHING — safe to re-run any time.
--   4. Verify       — reports row counts for sanity check.
--
-- SAFETY
--   - Single transaction.  Use Ctrl+C at the final prompt to ROLLBACK.
--   - Touches ONLY the 4 target tables.  Other WeCMS tenant data
--     (VN_VNM0004_000002 .. VN_VNM0004_000014) is PRESERVED.
--   - user_login_his is NOT re-seeded (12k+ rows for this tenant; not required
--     for the login feature to work — the app will build history on its own).
--
-- HOW TO RUN
--   psql "host=localhost port=5434 dbname=wecms_dev user=postgres" \
--        -v local_schema=public \
--        -f local_baseline_VN_VNM0004_000001_20260423.sql
--
--   (Developers set PGPASSWORD via env var — never commit the password.)
-- =============================================================================

\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
SELECT set_config('search_path', COALESCE(NULLIF(:'local_schema',''), 'public') || ', public', false);

BEGIN;

-- ----------------------------------------------------------------------------
-- Step 0 — Pre-flight: FK lookup rows required by busi_infm
-- ----------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM natn_infm WHERE ntnl_cd = 'VN') THEN
    RAISE EXCEPTION 'natn_infm.ntnl_cd = ''VN'' is missing — seed natn_infm first';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM chnl_infm WHERE chnl_id = 'VNM0004') THEN
    RAISE EXCEPTION 'chnl_infm.chnl_id = ''VNM0004'' is missing — seed chnl_infm first';
  END IF;
END $$;

-- ----------------------------------------------------------------------------
-- Step 1 — Cleanup: delete every row whose tenant is NOT VN_VNM0004_%
--          Order respects logical dependency (children before parents).
-- ----------------------------------------------------------------------------
\echo ''
\echo '==> [1/3] Cleaning non-VN_VNM0004 rows from the 4 target tables'

-- 1a. Login history for users NOT linked to any VN_VNM0004_% tenant
DELETE FROM user_login_his h
 WHERE h.user_id NOT IN (
   SELECT user_id FROM user_busi_conn_infm WHERE biz_key LIKE 'VN_VNM0004_%'
 );

-- 1b. User↔business connections on non-VN_VNM0004 tenants
DELETE FROM user_busi_conn_infm
 WHERE biz_key NOT LIKE 'VN_VNM0004_%';

-- 1c. Users that end up with NO connection to any VN_VNM0004_% tenant
DELETE FROM user_infm u
 WHERE NOT EXISTS (
   SELECT 1 FROM user_busi_conn_infm c
    WHERE c.user_id = u.user_id
      AND c.biz_key LIKE 'VN_VNM0004_%'
 );

-- 1d. Businesses on non-VN_VNM0004 tenants
DELETE FROM busi_infm
 WHERE biz_key NOT LIKE 'VN_VNM0004_%';

-- ----------------------------------------------------------------------------
-- Step 2 — Seed baseline tenant VN_VNM0004_000001 + its 99 users/connections
--          All inserts are idempotent via ON CONFLICT DO NOTHING.
-- ----------------------------------------------------------------------------
\echo ''
\echo '==> [2/3] Seeding baseline VN_VNM0004_000001 (1 busi + 99 users + 99 conns)'

-- -- 2a. busi_infm — baseline root row -----------------------------------------

-- -- 2b. user_infm — 99 users linked to VN_VNM0004_000001 ----------------------

-- -- 2c. user_busi_conn_infm — 99 user↔business connection rows ---------------

-- ----------------------------------------------------------------------------
-- Step 3 — Verify
-- ----------------------------------------------------------------------------
\echo ''
\echo '==> [3/3] Verifying counts — cross-tenant rows must be ZERO'

SELECT 'busi_infm VN_VNM0004_%'              AS tbl, COUNT(*)::bigint AS rows FROM busi_infm           WHERE biz_key LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'busi_infm _000001',                 COUNT(*)                FROM busi_infm           WHERE biz_key = 'VN_VNM0004_000001'
UNION ALL SELECT 'busi_infm NON-WeCMS (must=0)',      COUNT(*)                FROM busi_infm           WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'user_busi_conn _000001',            COUNT(*)                FROM user_busi_conn_infm WHERE biz_key = 'VN_VNM0004_000001'
UNION ALL SELECT 'user_busi_conn NON-WeCMS (must=0)', COUNT(*)                FROM user_busi_conn_infm WHERE biz_key NOT LIKE 'VN_VNM0004_%'
UNION ALL SELECT 'user_infm total (scope)',           COUNT(*)                FROM user_infm u
                                                         WHERE EXISTS (SELECT 1 FROM user_busi_conn_infm c
                                                                        WHERE c.user_id=u.user_id AND c.biz_key LIKE 'VN_VNM0004_%')
UNION ALL SELECT 'user_infm orphans (must=0)',        COUNT(*)                FROM user_infm u
                                                         WHERE NOT EXISTS (SELECT 1 FROM user_busi_conn_infm c
                                                                            WHERE c.user_id=u.user_id AND c.biz_key LIKE 'VN_VNM0004_%')
UNION ALL SELECT 'user_login_his orphans (must=0)',   COUNT(*)                FROM user_login_his h
                                                         WHERE h.user_id NOT IN (SELECT user_id FROM user_busi_conn_infm
                                                                                  WHERE biz_key LIKE 'VN_VNM0004_%')
ORDER BY 1;

-- Expected after a clean run on an otherwise empty local DB:
--   busi_infm _000001                = 1
--   busi_infm NON-WeCMS              = 0
--   user_busi_conn _000001           = 99
--   user_busi_conn NON-WeCMS         = 0
--   user_infm total (scope)          = 99
--   user_infm orphans                = 0
--   user_login_his orphans           = 0

\echo ''
\echo '==> About to COMMIT. Ctrl+C to ROLLBACK if counts look wrong.'
\prompt 'Press ENTER to COMMIT, Ctrl+C to abort: ' confirm

COMMIT;

\echo ''
\echo '==> LOCAL baseline refresh complete for VN_VNM0004_000001.'
